lib/metric.zs:
fn factor() -> number:
    return 1000

export fn to_meters(value: number) -> number:
    return value * factor()

test "Conversion":
    require to_meters(2) == 2000, "Two kilometers are 2000 meters."

lib/imperial.zs:
fn factor() -> number:
    return 3

export fn to_feet(value: number) -> number:
    return value * factor()

test "Conversion":
    require to_feet(2) == 6, "Two yards are six feet."
